python3 -c 'g=[[0]*17 for _ in range(14)]; pts=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)];
for r,c in pts:g[r][c]=2
# MST nearest axis-aligned edges via Kruskal, horizontal-first
edges=[]
for i,p in enumerate(pts):
 for j,q in enumerate(pts[:i]): edges.append((abs(p[0]-q[0])+abs(p[1]-q[1]),i,j))
par=list(range(len(pts)))
def f(x):
 while par[x]!=x:x=par[x]
 return x
for d,i,j in sorted(edges):
 a,b=f(i),f(j)
 if a!=b:
  par[a]=b;r,c=pts[i];rr,cc=pts[j]
  while c!=cc:
   c+=1 if cc>c else -1
   if (r,c) not in pts:g[r][c]=3
  while r!=rr:
   r+=1 if rr>r else -1
   if (r,c) not in pts:g[r][c]=3
print("\n".join(" ".join(map(str,x)) for x in g)); print(set(map(len,g)))'

